#!/usr/bin/env python3
"""Compute lenient and strict session funnels from JSONL event logs.

Lenient mode : a session counts for a stage if the action appears anywhere
               in the session, regardless of order.
Strict mode  : a session counts for a stage only if its actions appear in
               the canonical order view -> add_to_cart -> checkout ->
               purchase (each observed stage must come after the previous
               one). A checkout without an earlier add_to_cart does NOT
               count at the checkout stage under strict mode.

Usage: python3 funnel.py [logs.jsonl] [-o funnel_report.json]
"""
import argparse
import json
import sys

STAGES = ["view", "add_to_cart", "checkout", "purchase"]


def load_sessions(path: str) -> dict:
    """Group events by session_id -> ordered list of actions (by ts, stable)."""
    sessions = {}
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            sessions.setdefault(rec["session_id"], []).append(rec)
    # Sort each session's events by timestamp (stable keeps insertion order on ties).
    for evs in sessions.values():
        evs.sort(key=lambda r: r["ts"])
    return sessions


def strict_prefix_len(actions: list) -> int:
    """Longest prefix of STAGES matched in order by the given action sequence."""
    idx = 0
    for a in actions:
        if idx < len(STAGES) and a == STAGES[idx]:
            idx += 1
    return idx


def compute(sessions: dict) -> dict:
    total = len(sessions)
    result = {}
    for mode in ("lenient", "strict"):
        counts = {s: 0 for s in STAGES}
        for evs in sessions.values():
            actions = [e["action"] for e in evs]
            if mode == "lenient":
                present = set(actions)
                for i, stage in enumerate(STAGES):
                    if stage in present:
                        counts[stage] += 1
            else:
                depth = strict_prefix_len(actions)
                for stage in STAGES[:depth]:
                    counts[stage] += 1
        stages = {}
        prev = None
        for stage in STAGES:
            n = counts[stage]
            if prev is None:
                pct = round(n / total * 100, 1) if total else 0.0
            else:
                pct = round(n / prev * 100, 1) if prev else 0.0
            stages[stage] = {"count": n, "pct": pct}
            prev = n
        result[mode] = stages
    return result


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("logs", nargs="?", default="logs.jsonl")
    ap.add_argument("-o", "--out", default="funnel_report.json")
    args = ap.parse_args()

    try:
        sessions = load_sessions(args.logs)
    except FileNotFoundError:
        sessions = {}

    report = compute(sessions)
    with open(args.out, "w") as f:
        json.dump(report, f, indent=2)
    return 0


if __name__ == "__main__":
    sys.exit(main())

