"""Tests for the session funnel pipeline (generator + funnel.py)."""
import json
import os
import subprocess
import sys

import pytest

HERE = os.path.dirname(os.path.abspath(__file__))
GEN = os.path.join(HERE, "generate_logs.py")
FUNNEL = os.path.join(HERE, "funnel.py")
STAGES = ["view", "add_to_cart", "checkout", "purchase"]


def run(*cmd):
    return subprocess.run(
        [sys.executable, *cmd], capture_output=True, text=True, cwd=HERE
    )


@pytest.fixture(scope="module")
def report(tmp_path_factory):
    tmp = tmp_path_factory.mktemp("funnelrun")
    logs = tmp / "logs.jsonl"
    out = tmp / "funnel_report.json"
    r = run(GEN, str(logs))
    assert r.returncode == 0, r.stderr
    r = run(FUNNEL, str(logs), "-o", str(out))
    assert r.returncode == 0, r.stderr
    with open(out) as f:
        return json.load(f)


@pytest.fixture(scope="module")
def sessions(tmp_path_factory):
    """Parsed per-session action lists from the generated logs."""
    tmp = tmp_path_factory.mktemp("funnelrun")
    logs = tmp / "logs.jsonl"
    assert run(GEN, str(logs)).returncode == 0
    by_session = {}
    with open(logs) as f:
        for line in f:
            rec = json.loads(line)
            by_session.setdefault(rec["session_id"], []).append(rec)
    for evs in by_session.values():
        evs.sort(key=lambda r: r["ts"])
    return by_session


def test_planted_anomalies(sessions):
    """Exactly 10 sessions do checkout without a prior add_to_cart."""
    anomalies = [
        sid
        for sid, evs in sessions.items()
        if any(e["action"] == "checkout" for e in evs)
        and not any(e["action"] == "add_to_cart" for e in evs)
    ]
    assert len(anomalies) == 10


def test_lenient_counts(report):
    lenient = {s: report["lenient"][s]["count"] for s in STAGES}
    assert lenient == {
        "view": 200,
        "add_to_cart": 120,
        "checkout": 60,
        "purchase": 45,
    }


def test_strict_counts(report):
    strict = {s: report["strict"][s]["count"] for s in STAGES}
    assert strict == {
        "view": 200,
        "add_to_cart": 120,
        "checkout": 50,
        "purchase": 45,
    }


def test_funnels_differ_at_checkout_by_10(report):
    for stage in ("view", "add_to_cart", "purchase"):
        assert report["lenient"][stage]["count"] == report["strict"][stage]["count"]
    diff = report["lenient"]["checkout"]["count"] - report["strict"]["checkout"]["count"]
    assert diff == 10


def test_pct_math_rounded_to_1_decimal(report):
    # Lenient: view 200 -> cart 120 -> checkout 60 -> purchase 45
    assert report["lenient"]["view"]["pct"] == round(200 / 200 * 100, 1)      # 100.0
    assert report["lenient"]["add_to_cart"]["pct"] == round(120 / 200 * 100, 1)  # 60.0
    assert report["lenient"]["checkout"]["pct"] == round(60 / 120 * 100, 1)   # 50.0
    assert report["lenient"]["purchase"]["pct"] == round(45 / 60 * 100, 1)    # 75.0
    # Strict: cart 120 -> checkout 50 -> purchase 45
    assert report["strict"]["checkout"]["pct"] == round(50 / 120 * 100, 1)    # 41.7
    assert report["strict"]["purchase"]["pct"] == round(45 / 50 * 100, 1)     # 90.0
    # All pcts are rounded to at most 1 decimal place.
    for mode in ("lenient", "strict"):
        for s in STAGES:
            p = report[mode][s]["pct"]
            assert p == round(p, 1)


def test_empty_input_produces_zeros_without_crash(tmp_path):
    empty = tmp_path / "empty.jsonl"
    empty.write_text("")
    out = tmp_path / "empty_report.json"
    r = run(FUNNEL, str(empty), "-o", str(out))
    assert r.returncode == 0, r.stderr
    rep = json.loads(out.read_text())
    for mode in ("lenient", "strict"):
        for s in STAGES:
            assert rep[mode][s]["count"] == 0
            assert rep[mode][s]["pct"] == 0.0

